  loadAllEmpViews: async () => { try { const r=await fetch(`${FIREBASE_URL}/emp_views.json`); if(!r.ok)return null; const d=await r.json(); if(!d||typeof d!=="object")return{}; const src=Array.isArray(d)?d.reduce((a,v,i)=>v?(a[i]=v,a):a,{}):d; const out={};Object.entries(src).forEach(([k,v])=>{if(!v||typeof v!=="object")return;const keys=Object.keys(v);out[k]=keys.every(k2=>!isNaN(Number(k2)))?Object.values(v).filter(x=>typeof x==="string"):keys.filter(k2=>v[k2]===true);});return out; } catch{return null;} },
